# Intent
  arrangeManager: discovery, slot auto-allocation, placement, reswing.

# Helpers
  @fn mkAm(harness, opts)  @ 7-12
  @fn seedTracks(h, specs)  @ 18-40
      -- Seed two arbitrary tracks and a per-track item list. Returns the
      -- track tokens so each test can name them. The harness's default
      -- bindTake(take1) is unrelated — we manage these via setProjectTracks
      -- so am sees them in CountTracks/GetTrack order.
  @fn slotFor(am, trackIdx, id)  @ 42-44
  @fn slotAt(am, trackIdx, slotIdx)  @ 46-48

# Cases
  @case 'projectTracks lists every track in REAPER order with item count'  [harness]  @ 55-71
  @case 'trackSlots auto-allocates slot indices for live takes'  [harness]  @ 78-92
  @case 'tracksTakes assigns slotIdx to every grouped take'  [harness]  @ 96-114
  @case 'ensureSlots is idempotent — second read does not reallocate'  [harness]  @ 118-129
  @case 'hasPlacedTakes ignores parked takes, sees placed instances'  [harness]  @ 133-142
  @case 'ownerTrack resolves a parked take to its logical track, not scratch'  [harness]  @ 149-163
  @case 'renameSlot writes SetTakeName across every matching item'  [harness]  @ 170-183
  @case 'renameSlot reroots the family, each slot keeping its own ordinal'  [harness]  @ 187-204
  @case 'renameSlot with a changed ordinal renames that slot alone'  [harness]  @ 208-218
  @case 'two slots holding the root plain are namesakes, not a family'  [harness]  @ 222-234
  @case 'with the root held plain twice, a variant reroots neither'  [harness]  @ 238-250
  @case 'an unnamed slot has no family'  [harness]  @ 254-264
  @case 'the reroot reaches a parked family member'  [harness]  @ 268-277
  @case 'renameSlot renames a parked slot through its keeper'  [harness]  @ 281-288
  @case 'deleteSlot removes every matching item and prunes the dict entry'  [harness]  @ 292-310
  @case 'pruneSlots forever-deletes every parked slot, MIDI and audio alike'  [harness]  @ 314-336
  @case 'createAndDropMidi mints slot 0, creates a take, names it'  [harness]  @ 343-359
  @case 'createAndDropMidi allocates lowest-free index across calls'  [harness]  @ 363-374
  @case 'dropInstance pools to an existing slot'  [harness]  @ 378-389
  @case 'dropInstance overwrites a take already starting at the drop position'  [harness]  @ 393-410
  @case 'createAndDropMidi overwrites a take already starting at the create position'  [harness]  @ 414-429
  @case 'dropInstance returns nil for missing slot or missing track'  [harness]  @ 433-439
  @case 'duplicateTake clones a MIDI take into a pooled sibling'  [harness]  @ 443-458
  @case 'dropInstance and duplicateTake name the new take after the slot'  [harness]  @ 462-473
  @case 'duplicateTake returns nil for a missing track'  [harness]  @ 477-485
  @case 'dropInstance carries the sibling MIDI events into the new instance'  [harness]  @ 489-499
  @case 'duplicateTake carries the source MIDI events into the clone'  [harness]  @ 503-514
  @case 'startIsClear only collides on an exact start match (item ~= exceptItem)'  [harness]  @ 518-533
  @case 'createAndDropMidi returns nil when no track exists'  [harness]  @ 537-542
  @case 'keyForSlot maps 0..61 through util.toBase62'  [harness]  @ 549-558
  @case 'takesUsing scans each take swing map (ds) for the named swing'  [harness]  @ 565-583
  @case 'tempersInUse unions take/project temper names, minus the 12EDO floor'  [harness]  @ 586-600
  @case 'tracksTakes relayouts on read: an OPEN take grows to its source length'  [harness]  @ 610-619
  @case 'build relayout: OPEN takes fill to source; an earlier one capped at its gap (no overlap)'  [harness]  @ 622-633
  @case 'build relayout: an OPEN take whose item outruns its shrunk source is pulled back'  [harness]  @ 636-644
  @case 'a later take truncates an earlier one; deleting the later regrows it'  [harness]  @ 648-662
  @case 'resizeTake stores a numeric natural; ≥ source demotes back to util.OPEN'  [harness]  @ 666-682
  @case 'audio take longer than its source keeps its length across a move'  [harness]  @ 685-700
  @case 'trimmed audio take keeps its trim across a move (no balloon to source)'  [harness]  @ 703-715
  @case 'moveTake shifts start; refused on start-collision; returns ok flag'  [harness]  @ 719-730
  @case 'resizeTake writes natural; rendered is min(natural, source, gap)'  [harness]  @ 734-745
  @case 'trimHead walks the start edge in, holding the content and the end still'  [harness]  @ 749-765
  @case 'a head is refused before the origin, at the source end, or onto an occupied start'  [harness]  @ 768-779
  @case 'tailQN is the source past the rendered end, whatever shortened the take'  [harness]  @ 782-791
  @case 'head, rendered length and tail partition the source'  [harness]  @ 794-806
  @case 'a trimmed take is capped by the gap, and regrows to source-minus-head without one'  [harness]  @ 809-822
  @case 'trimming the head of a resized take keeps the end where the resize put it'  [harness]  @ 825-836
  @case 'splitTake cuts a take into two pooled halves that meet at the cut'  [harness]  @ 842-859
  @case 'the lower half inherits the natural, so the pair ends where the whole did'  [harness]  @ 862-874
  @case 'splitting a head-trimmed take leaves both halves on the source origin'  [harness]  @ 877-891
  @case 'a split is refused on either edge, off the take, and on audio'  [harness]  @ 894-907
  @case 'deleteTake removes the item, leaving the other take intact'  [harness]  @ 911-922
  @case 'deleteTake parks a slot\'s last instance; the slot survives, greyed'  [harness]  @ 928-944
  @case 'deleteTake of a non-last instance deletes outright (no park)'  [harness]  @ 948-963
  @case 're-dropping from a parked slot re-materialises off the keeper'  [harness]  @ 967-980
  @case 'deleteSlot forever-deletes: live instances and the parked keeper'  [harness]  @ 984-997
  @case 'deleteSlot forever-deletes the pool per-event metadata'  [harness]  @ 1001-1012
  @case 'mintParkedTake shows the new slot at once; isParkedTake flags scratch-hosted takes'  [harness]  @ 1016-1031
  @case 'vary replaces the instance with one of a fresh variant slot'  [harness]  @ 1038-1060
  @case 'vary numbers from the family high-water mark; a variant of a variant joins the family'  [harness]  @ 1064-1075
  @case 'vary refuses on a slot with a single instance'  [harness]  @ 1079-1087
  @case 'stepVariant moves the placement onto the next slot of the family'  [harness]  @ 1094-1113
  @case 'stepVariant past the last of the family varies'  [harness]  @ 1117-1130
  @case 'stepVariant off the front of the family does nothing'  [harness]  @ 1134-1145
  @case 'stepping back off a variant parks it; stepping on again brings it live'  [harness]  @ 1149-1169
  @case 'a variant with two namesake bases steps forward but not back'  [harness]  @ 1173-1189
  @case 'findTake resolves a REAPER take handle back to its grid take-shape'  [harness]  @ 1196-1210
  @case 'initialCursor reads the selected item: its take track and start'  [harness]  @ 1214-1226
  @case 'initialCursor falls back to the edit cursor and selected track'  [harness]  @ 1230-1239
  @case 'initialCursor defaults to track 0 when nothing is selected'  [harness]  @ 1243-1251
  @case 'editCursorQN reads the REAPER edit cursor'  [harness]  @ 1258-1263
  @case 'setEditCursorQN moves the REAPER edit cursor'  [harness]  @ 1267-1272
  @case 'loopRangeQN returns the project loop range'  [harness]  @ 1276-1283
  @case 'loopRangeQN is nil when no loop is set'  [harness]  @ 1287-1291
  @case 'setLoopRangeQN writes the project loop range'  [harness]  @ 1295-1302
  @case 'loopTo brackets a span: loop range, repeat on, cursor at its start'  [harness]  @ 1306-1314
  @case 'loopTo leaves the cursor alone when the play head is inside the span'  [harness]  @ 1318-1327
  @case 'clearLoopRange removes the project loop range'  [harness]  @ 1331-1337
  @case 'playPositionQN is nil when the transport is stopped'  [harness]  @ 1341-1345
  @case 'playPositionQN returns the play head qn while playing'  [harness]  @ 1349-1354
  @case 'seekInstance takes the instance whose rendered span holds qn'  [harness]  @ 1361-1375
  @case 'seekInstance spans are half-open — the end belongs to the next'  [harness]  @ 1379-1388
  @case 'seekInstance from a gap travels forwards by default, backwards when asked'  [harness]  @ 1392-1404
  @case 'seekInstance falls back to the other direction when its own is empty'  [harness]  @ 1408-1418
  @case 'seekInstance ignores instances of other slots'  [harness]  @ 1422-1434
  @case 'seekInstance matches on the rendered span, not the source span'  [harness]  @ 1438-1450
  @case 'seekInstance is nil for a slot whose only take is parked'  [harness]  @ 1454-1464
  @case 'projectEndQN is 0 for a project with no items'  [harness]  @ 1468-1472
  @case 'projectEndQN reports the largest take end across all tracks'  [harness]  @ 1476-1485
  @case 'freeSpan is the gap to the next take, and unbounded past the last'  [harness]  @ 1492-1502
  @case 'duplicateBelow places a pooled clone at the append point'  [harness]  @ 1506-1522
  @case 'duplicateBelow refuses where a truncating neighbour leaves no room'  [harness]  @ 1526-1542
  @case 'duplicateBelow refuses where the gap is shorter than the natural length'  [harness]  @ 1546-1557
  @case 'duplicateBelow refuses on exact-start collision at the destination'  [harness]  @ 1561-1571
  @case 'duplicateBelow refuses on audio takes'  [harness]  @ 1575-1584
  @case 'newTakeBelow creates an empty MIDI take of the asked-for length at the append point'  [harness]  @ 1588-1609
  @case 'newTakeBelow parks the take for want of room'  [harness]  @ 1613-1625
  @case 'newTakeBelow measures the room against the length asked for'  [harness]  @ 1629-1640
  @case 'newTakeBelow refuses on audio'  [harness]  @ 1644-1652
  @case 'distinct pool guids on different tracks get distinct colourIdx'  [harness]  @ 1657-1670
  @case 'pooled instances on different tracks share one colourIdx'  [harness]  @ 1674-1684
  @case 'createAndDropMidi stamps I_CUSTOMCOLOR on the new take'  [harness]  @ 1688-1696
  @case 'placement does not overwrite a pre-existing take colour (preserve override)'  [harness]  @ 1700-1712
  @case 'a recycled take handle reports the new item\'s pool, not the dead take\'s'  [harness]  @ 1717-1740

